$source = 'service/business-website-design.html'
$copy = 'service/business-website-design-in-nigeria.html'
$root = Get-Location
$c = [IO.File]::ReadAllText((Join-Path $root $source), [Text.UTF8Encoding]::new($false))

$newSection = @'
    <section class="bw-paper bw-section bw-fit"><div class="bw-shell"><div class="bw-fit-head"><p class="bw-kicker dark">Who we build for</p><h2 class="bw-h2 dark">Corporate, company and small business websites</h2><p>Business website needs differ by size, audience and what the organisation needs the site to achieve. We shape the structure around the business instead of forcing every project into the same template.</p></div><div class="bw-fit-grid"><article class="bw-fit-card"><span class="bw-fit-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M5 20V9l7-5 7 5v11H5Z M9 20v-6h6v6" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span><h3>Small business websites</h3><p>For a small business, the job is credibility and enquiries. A focused website can explain your services, show your work and make it obvious how to get in touch.</p></article><article class="bw-fit-card"><span class="bw-fit-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="5" y="3" width="14" height="18" rx="2" stroke="currentColor" stroke-width="1.8"/><path d="M8 7h8M8 11h8M8 15h3" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></span><h3>Company websites</h3><p>A company website often needs services, team information, documents, locations and contact routes to work together as one clear experience.</p></article><article class="bw-fit-card"><span class="bw-fit-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M4 20V9h5v11M10 20V4h5v16M16 20v-7h4v7" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span><h3>Corporate websites</h3><p>A corporate website may need to serve several internal audiences as well as customers, with clearer navigation for documents, branches, teams or press information.</p></article></div><p class="bw-fit-note">Whichever size you are, the website should begin with what the business needs to achieve before the visual details are decided.</p></div></section>
'@
$pattern = '(?s)    <section class="bw-paper bw-section" style="padding-top:0">.*?</section>'
$c = [regex]::Replace($c, $pattern, $newSection, 1)

$css = @'
    .bw-fit-head{max-width:720px;margin:0 auto 58px;text-align:center}.bw-fit-head .bw-kicker{margin-bottom:18px}.bw-fit-head .bw-h2{font-size:clamp(2.3rem,4.5vw,4.8rem)}.bw-fit-head>p:last-child{max-width:650px;margin:22px auto 0;font-size:17px;line-height:1.75}.bw-fit-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.bw-fit-card{min-height:300px;padding:28px 24px 30px;border:1px solid var(--bw-paperline);border-radius:20px;background:#fff;box-shadow:0 10px 28px rgba(32,26,37,.04)}.bw-fit-icon{display:grid;place-items:center;width:38px;height:38px;margin-bottom:22px;border-radius:11px;background:#7355a7;color:#fff}.bw-fit-icon svg{width:21px;height:21px}.bw-fit-card h3{margin:0;color:var(--bw-dark);font:700 20px/1.25 Inter,sans-serif;letter-spacing:-.03em}.bw-fit-card p{margin:12px 0 0;font-size:14px;line-height:1.7}.bw-fit-note{max-width:740px;margin:28px auto 0;text-align:center;color:var(--bw-dark);font-size:15px;line-height:1.7}.bw-fit-note:before{content:"";display:block;width:52px;height:1px;margin:0 auto 18px;background:#7355a7}
    @media(max-width:900px){.bw-fit-grid{grid-template-columns:1fr 1fr}.bw-fit-card{min-height:0}}
    @media(max-width:620px){.bw-fit-head{margin-bottom:40px}.bw-fit-grid{grid-template-columns:1fr}.bw-fit-card{padding:25px 22px}}
'@
if ($c -notmatch 'bw-fit-grid') { $c = $c.Replace('  </style>', $css + '  </style>') }
[IO.File]::WriteAllText((Join-Path $root $source), $c, [Text.UTF8Encoding]::new($false))
Copy-Item (Join-Path $root $source) (Join-Path $root $copy) -Force
Write-Output 'Added and synchronized the audience-fit section.'
